## 2. Create MediaSessionService

Create `MusicService.java`:

```java:app/src/main/java/com/example/musicstreamproject2/service/MusicService.java
package com.example.musicstreamproject2.service;

import android.app.PendingIntent;
import android.content.Intent;
import android.os.Bundle;

import androidx.annotation.Nullable;
import androidx.media3.common.AudioAttributes;
import androidx.media3.common.C;
import androidx.media3.exoplayer.ExoPlayer;
import androidx.media3.session.MediaSession;
import androidx.media3.session.MediaSessionService;

import com.example.musicstreamproject2.MainActivity;

public class MusicService extends MediaSessionService {
 private MediaSession mediaSession = null;
 private ExoPlayer player;

 @Override
 public void onCreate() {
 super.onCreate();

 // Initialize ExoPlayer
 player = new ExoPlayer.Builder(this)
 .setAudioAttributes(AudioAttributes.DEFAULT, true)
 .setHandleAudioBecomingNoisy(true)
 .build();

 // Create session activity PendingIntent
 Intent sessionIntent = new Intent(this, MainActivity.class);
 PendingIntent sessionActivityPendingIntent = PendingIntent.getActivity(
 this, 0, sessionIntent, 
 PendingIntent.FLAG_IMMUTABLE | PendingIntent.FLAG_UPDATE_CURRENT
 );

 // Create MediaSession
 mediaSession = new MediaSession.Builder(this, player)
 .setSessionActivity(sessionActivityPendingIntent)
 .build();
 }

 @Nullable
 @Override
 public MediaSession onGetSession(MediaSession.ControllerInfo controllerInfo) {
 return mediaSession;
 }

 @Override
 public void onDestroy() {
 if (mediaSession != null) {
 mediaSession.getPlayer().release();
 mediaSession.release();
 mediaSession = null;
 }
 super.onDestroy();
 }

 public ExoPlayer getPlayer() {
 return player;
 }
}
```

