ng url = currentSong.getUrl();\n if (url != null) {\n MediaItem mediaItem = MediaItem.fromUri(Uri.parse(url));\n exoPlayer.setMediaItem(mediaItem);\n exoPlayer.setPlaybackParameters(new PlaybackParameters(1f));\n exoPlayer.prepare();\n exoPlayer.play();\n\n // Start background service\n Intent serviceIntent = new Intent(context, MusicService.class);\n serviceIntent.setAction(\"PLAY\");\n context.startForegroundService(serviceIntent);\n\n // Notify BaseActivity to show mini player\n if (context instanceof BaseActivity) {\n ((BaseActivity) context).showMiniPlayer(currentSong);\n }\n }\n }\n }\n\n public static void pausePlayer() {\n if (exoPlayer != null) {\n exoPlayer.pause();\n }\n }\n\n public static void resumePlayer() {\n if (exoPlayer != null) {\n exoPlayer.play();\n }\n }\n\n public static boolean isPlaying() {\n return exoPlayer != null && exoPlayer.isPlaying();\n }\n\n public static void releasePlayer() {\n if (exoPlayer != null) {\n exoPlayer.release();\n exoPlayer = null;\n currentSong = null;\n }\n }\n}"}"}}]},{"role":"tool","name":"edit_file","tool_call_id":"toolu_bdrk_018WyEydwnS1ZxuWJLjFHSWJ","content":"The apply model made the following changes to the file:

